templates.template:
// ################ DC / Login as user ################
//
// Colour strategy: the HUE comes from a core semantic token, the LIGHTNESS always comes from
// whatever surface the tint sits on. That is why nothing here can go unreadable on a dark skin --
// the accent is never used as a solid background behind text, only as a translucent sheet over the
// host surface and as a hard 2px edge.
//
// Only ONE level of xf-default() anywhere: CssRenderer substitutes it in a single non-recursive
// pass, so a nested xf-default() inside a fallback would survive into the compiled LESS and break
// the whole stylesheet. A bare @xf-* inside a fallback is fine -- that is handled by the next pass.
//
// Swap this one line if a board's attention colour clashes:
@dcLoginAsUser-accent:     xf-default(@xf-textColorAttention, #d18f2e);

@dcLoginAsUser-tintStrong: fade(@dcLoginAsUser-accent, 26%);
@dcLoginAsUser-tintSoft:   fade(@dcLoginAsUser-accent, 14%);

// ---------------- staff bar, impersonation active ----------------

.p-staffBar--dcLoginAsUser
{
	// Two identical stops = a flat translucent sheet. background-color is left alone, so whatever
	// the style set via the publicStaffBar css property still shows through and supplies the
	// lightness. Deliberately NOT xf-intensify(): that only moves lightness, so on a near-black
	// staff bar it yields a lighter grey that reads as "hover", not "you are impersonating".
	background-image: linear-gradient(@dcLoginAsUser-tintStrong, @dcLoginAsUser-tintStrong);
	box-shadow: inset 0 -2px 0 0 @dcLoginAsUser-accent;

	.p-staffBar-link:hover
	{
		background: @dcLoginAsUser-tintSoft;
	}
}

.dcLoginAsUser-status
{
	font-weight: 600;
	cursor: default;

	&:hover { background: none; }
}

.dcLoginAsUser-trigger .fa--xf,
.dcLoginAsUser-status .fa--xf,
.dcLoginAsUser-return .fa--xf
{
	margin-right: .35em;
}

// ---------------- return control ----------------

.dcLoginAsUser-returnForm
{
	display: inline-block;
	vertical-align: top;
	margin: 0;
}

.dcLoginAsUser-return
{
	// a <button> inherits none of this from .p-staffBar-link
	font: inherit;
	color: inherit;
	border: 0;
	cursor: pointer;

	background: @dcLoginAsUser-tintStrong;
	border-radius: @xf-borderRadiusSmall;
	box-shadow: inset 0 0 0 1px @dcLoginAsUser-accent;

	&:hover,
	&:focus
	{
		// stay in the same lightness family -- on a dark skin, lightening the background here would
		// put light text on a light ground.
		background: fade(@dcLoginAsUser-accent, 40%);
		text-decoration: none;
	}
}

// ---------------- overlays ----------------

.dcLoginAsUser-target
{
	display: flex;
	align-items: center;
	gap: @xf-paddingMedium;
}

.dcLoginAsUser-target-main
{
	min-width: 0;
}

.dcLoginAsUser-flag
{
	display: inline-block;
	padding: 1px @xf-paddingSmall;
	border-radius: @xf-borderRadiusSmall;
	font-size: @xf-fontSizeSmallest;
	background: @dcLoginAsUser-tintSoft;
	box-shadow: inset 0 0 0 1px @dcLoginAsUser-accent;

	.fa--xf { margin-right: .25em; }
}

.dcLoginAsUser-recent
{
	margin: 0;
	padding: 0;
	list-style: none;
}

.dcLoginAsUser-recent-item
{
	border-top: @xf-borderSize solid @xf-borderColorLight;

	&:first-child { border-top: 0; }

	> a
	{
		display: block;
		padding: @xf-paddingMedium 0;

		&:hover
		{
			background: @dcLoginAsUser-tintSoft;
			text-decoration: none;
		}
	}
}
